Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Aperture f-number N: <output id="apertureFNumberVal">4</output><input id="apertureFNumberInput" type="range" min="1.4" max="16" step="0.1" value="4" oninput="document.getElementById('apertureFNumberVal').value=this.value;update_apertureFNumber(+this.value)"></label><label>Focus object distance U: <output id="objectDistanceUVal">6</output><input id="objectDistanceUInput" type="range" min="2" max="20" step="0.1" value="6" oninput="document.getElementById('objectDistanceUVal').value=this.value;update_objectDistanceU(+this.value)"></label><span id="demoNarration" style="margin:0;font-size:10px;max-width:180px"></span><span><button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 1200, 680);

var W = 1200, H = 680;
var scene = draw.group();
var state = { apertureFNumber: 4, objectDistanceU: 6 };
var currentStep = 0;

var steps = [
  {
    title: 'Wide aperture, shallow depth of field',
    narration: 'With a low f-number, the aperture is wide and the ray cone is steep. Points slightly in front of or behind the focused object distance form a large circle of confusion, so the acceptable depth range is short.',
    state: { apertureFNumber: 2, objectDistanceU: 6 }
  },
  {
    title: 'Stop down the lens',
    narration: 'Increasing the f-number narrows the aperture. The same defocused object points now make smaller blur circles on the sensor, so the near and far depth-of-field limits move farther apart.',
    state: { apertureFNumber: 11, objectDistanceU: 6 }
  },
  {
    title: 'Refocus farther away',
    narration: 'Moving the focused object plane farther from the lens shifts the geometry of the ray bundles. The depth-of-field limits move with the focus distance, and the far limit expands differently from the near limit.',
    state: { apertureFNumber: 11, objectDistanceU: 14 }
  }
];

var lensX = 760;
var sensorX = 930;
var cy = 330;
var blue = '#0b3cff';
var paleBlue = '#6f78ff';
var red = '#d21f00';
var planeRed = '#ff4b4b';
var black = '#000000';

function addTip(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
  return el;
}

function txt(g, s, x, y, size, fill, italic, anchor) {
  var t = g.text(s).font({
    family: 'Georgia, Times New Roman, serif',
    size: size,
    style: italic ? 'italic' : 'normal',
    anchor: anchor || 'middle'
  }).fill(fill || black);
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': Math.max(2, size * 0.13), 'stroke-linejoin': 'round' });
  t.center(x, y);
  return t;
}

function dotted(g, x1, y1, x2, y2, w) {
  return g.line(x1, y1, x2, y2).stroke({ color: black, width: w || 1.4, dasharray: '1.5,4', linecap: 'round' });
}

function line(g, x1, y1, x2, y2, color, w, op) {
  return g.line(x1, y1, x2, y2).stroke({ color: color, width: w, linecap: 'round', linejoin: 'round' }).opacity(op == null ? 1 : op);
}

function arrowHead(g, x, y, angle, color, size, op) {
  var s = size || 12;
  var p1 = [x, y];
  var p2 = [x - s * Math.cos(angle - 0.45), y - s * Math.sin(angle - 0.45)];
  var p3 = [x - s * Math.cos(angle + 0.45), y - s * Math.sin(angle + 0.45)];
  return g.polygon([p1, p2, p3].map(function (p) { return p.join(','); }).join(' ')).fill(color).opacity(op == null ? 1 : op);
}

function arrow(g, x1, y1, x2, y2, color, w, both, op) {
  var a = Math.atan2(y2 - y1, x2 - x1);
  line(g, x1, y1, x2, y2, color, w, op);
  arrowHead(g, x2, y2, a, color, 14, op);
  if (both) arrowHead(g, x1, y1, a + Math.PI, color, 14, op);
}

function distToX(d) {
  var span = 700, q = 10;
  return lensX - span * d / (d + q);
}

function imageDistance(d) {
  var f = 1;
  return f * d / Math.max(0.05, d - f);
}

function convergenceX(d, u) {
  var raw = lensX + (sensorX - lensX) * (imageDistance(d) / imageDistance(u));
  return sensorX + (raw - sensorX) * 5.2;
}

function dofLimits(u, n) {
  var f = 1, c = 0.006;
  var Hh = f * f / (n * c) + f;
  var near = (Hh * u) / (Hh + (u - f));
  var far = (Hh > (u - f)) ? (Hh * u) / (Hh - (u - f)) : 120;
  far = Math.min(far, 120);
  return { near: near, far: far, hyper: Hh };
}

function yAtSensor(apY, xConv) {
  return apY + (cy - apY) * (sensorX - lensX) / (xConv - lensX);
}

function render() {
  scene.clear();

  var n = state.apertureFNumber;
  var u = state.objectDistanceU;
  var lim = dofLimits(u, n);
  var xU = distToX(u);
  var xD1 = distToX(lim.near);
  var xD2 = distToX(lim.far);
  var apHalf = Math.max(8, Math.min(70, 130 / n));
  var lensHalf = 132;
  var narrowAmount = Math.max(0, Math.min(1, (n - 2) / 9));

  scene.rect(W, H).fill('#ffffff');

  line(scene, 70, cy, 1055, cy, '#d8d8d8', 1.1, 0.85);
  txt(scene, 'optical axis', 170, cy - 18, 16, '#777', false, 'middle').opacity(0.7);

  dotted(scene, xD2, cy + 38, xD2, 628, 1.6);
  dotted(scene, xU, cy + 22, xU, 604, 1.4);
  dotted(scene, xD1, cy + 38, xD1, 628, 1.6);

  line(scene, xU, 70, xU, 610, planeRed, 1.2, 0.95);
  line(scene, sensorX, 70, sensorX, 610, planeRed, 1.2, 0.95);
  line(scene, lensX, 70, lensX, 610, blue, 1.6, 0.9);

  txt(scene, 'object plane', Math.max(132, Math.min(690, xU + 12)), 76, 24, black, false, 'middle');
  txt(scene, 'sensor plane', sensorX + 95, 78, 24, black, false, 'middle');

  dotted(scene, xD2, 545, lensX, 545, 1.2);
  dotted(scene, xU, 574, lensX, 574, 1.2);
  dotted(scene, xD1, 516, lensX, 516, 1.2);
  txt(scene, 'D₂', (xD2 + xU) / 2 - 5, 527, 30, black, true, 'middle');
  txt(scene, 'U', (xU + lensX) / 2, 555, 30, black, true, 'middle');
  txt(scene, 'D₁', (xD1 + lensX) / 2, 498, 30, black, true, 'middle');

  dotted(scene, xD2, 622, xD1, 622, 1.3);
  dotted(scene, xD2, 606, xD2, 638, 1.3);
  dotted(scene, xD1, 606, xD1, 638, 1.3);
  txt(scene, 'depth of field', (xD2 + xD1) / 2, 606, 22, black, false, 'middle');

  var redY = 654;
  arrow(scene, xD2 + 6, redY, xD1 - 6, redY, red, 3, true, 0.25 + 0.75 * narrowAmount);
  txt(scene, 'larger depth of field', Math.max(190, (xD2 + xD1) / 2), redY - 24, 21, red, false, 'middle').opacity(0.25 + 0.75 * narrowAmount);

  var lensPath = 'M ' + (lensX - 5) + ' ' + (cy - lensHalf) +
    ' C ' + (lensX - 38) + ' ' + (cy - 70) + ' ' + (lensX - 38) + ' ' + (cy + 70) + ' ' + (lensX - 5) + ' ' + (cy + lensHalf) +
    ' M ' + (lensX + 5) + ' ' + (cy - lensHalf) +
    ' C ' + (lensX + 38) + ' ' + (cy - 70) + ' ' + (lensX + 38) + ' ' + (cy + 70) + ' ' + (lensX + 5) + ' ' + (cy + lensHalf);
  var lens = scene.path(lensPath).fill('none').stroke({ color: black, width: 3.5, linecap: 'round' });
  addTip(lens, 'Convex lens and aperture stop', 'Lens aperture', 'The black opening at the lens controls the width of the ray cone. A higher f-number means a smaller opening.');

  line(scene, lensX - 26, cy - apHalf, lensX + 26, cy - apHalf, black, 2.4, 1);
  line(scene, lensX - 26, cy + apHalf, lensX + 26, cy + apHalf, black, 2.4, 1);
  line(scene, lensX - 26, cy - lensHalf, lensX - 26, cy - apHalf, black, 2.2, 1);
  line(scene, lensX - 26, cy + apHalf, lensX - 26, cy + lensHalf, black, 2.2, 1);

  dotted(scene, lensX - 48, cy - apHalf, lensX - 48, cy + apHalf, 1.2);
  line(scene, lensX - 54, cy - apHalf, lensX - 42, cy - apHalf, black, 1.4, 1);
  line(scene, lensX - 54, cy + apHalf, lensX - 42, cy + apHalf, black, 1.4, 1);
  txt(scene, 'A = f/N', lensX - 95, cy + 5, 26, black, true, 'middle');

  line(scene, lensX - 76, cy - lensHalf, lensX - 76, cy - apHalf - 15, black, 1.8, 1);
  line(scene, lensX - 82, cy - lensHalf, lensX - 70, cy - lensHalf, black, 1.8, 1);
  line(scene, lensX - 82, cy - apHalf - 15, lensX - 70, cy - apHalf - 15, black, 1.8, 1);
  txt(scene, 'f', lensX - 76, cy - 78, 28, black, true, 'middle');

  if (n > 5) {
    arrow(scene, lensX + 54, cy - lensHalf + 2, lensX + 54, cy - apHalf - 8, red, 3, false, narrowAmount);
    arrow(scene, lensX + 54, cy + lensHalf - 2, lensX + 54, cy + apHalf + 8, red, 3, false, narrowAmount);
    txt(scene, 'narrowed\naperture', lensX + 102, cy + 118, 20, red, false, 'start').opacity(narrowAmount);
  }

  var xFocusSensor = sensorX;
  var yTop = cy - apHalf;
  var yBot = cy + apHalf;

  line(scene, xU, cy, lensX, yTop, blue, 2.2, 0.8);
  line(scene, lensX, yTop, xFocusSensor, cy, blue, 2.2, 0.8);
  line(scene, xU, cy, lensX, yBot, blue, 2.2, 0.8);
  line(scene, lensX, yBot, xFocusSensor, cy, blue, 2.2, 0.8);
  var fp = scene.circle(8).center(xU, cy).fill(black);
  addTip(fp, 'Focused object point at distance U', 'Focused distance U', 'Rays from this object distance meet exactly on the sensor, so its blur is ideally a point.');

  var dTest = Math.min(95, u + Math.max(3.2, u * 0.48));
  var xTest = distToX(dTest);
  var xConv = convergenceX(dTest, u);
  var ysT = yAtSensor(yTop, xConv);
  var ysB = yAtSensor(yBot, xConv);

  line(scene, xTest, cy, lensX, yTop, blue, 3, 1);
  line(scene, lensX, yTop, sensorX, ysT, blue, 3, 1);
  line(scene, xTest, cy, lensX, yBot, blue, 3, 1);
  line(scene, lensX, yBot, sensorX, ysB, blue, 3, 1);
  scene.circle(6).center(xConv, cy).fill(blue).opacity(0.8);
  addTip(scene.circle(9).center(xConv, cy).fill('#fff').opacity(0.01), 'Ray convergence point away from the sensor', 'Defocus convergence', 'For an object not at the focused distance, the ray cone comes to a point before or after the sensor. The sensor cuts the cone while it still has a finite width.');

  [lim.near, lim.far].forEach(function (d, idx) {
    var xo = distToX(d);
    var xc = convergenceX(d, u);
    var col = idx === 0 ? paleBlue : paleBlue;
    line(scene, xo, cy, lensX, yTop, col, 1.1, 0.62);
    line(scene, lensX, yTop, sensorX, yAtSensor(yTop, xc), col, 1.1, 0.62);
    line(scene, xo, cy, lensX, yBot, col, 1.1, 0.62);
    line(scene, lensX, yBot, sensorX, yAtSensor(yBot, xc), col, 1.1, 0.62);
  });

  var blurTop = Math.min(ysT, ysB);
  var blurBot = Math.max(ysT, ysB);
  var minBlur = 7;
  if (blurBot - blurTop < minBlur) {
    var mid = (blurTop + blurBot) / 2;
    blurTop = mid - minBlur / 2;
    blurBot = mid + minBlur / 2;
  }
  var blur = line(scene, sensorX + 27, blurTop, sensorX + 27, blurBot, black, 2.2, 1);
  line(scene, sensorX + 20, blurTop, sensorX + 34, blurTop, black, 2, 1);
  line(scene, sensorX + 20, blurBot, sensorX + 34, blurBot, black, 2, 1);
  txt(scene, 'C', sensorX + 52, (blurTop + blurBot) / 2, 24, black, false, 'middle');
  txt(scene, 'circle of\nconfusion', sensorX + 116, (blurTop + blurBot) / 2, 21, black, false, 'start');
  addTip(blur, 'Circle of confusion: blur diameter on the sensor', 'Circle of confusion', 'The same defocus produces a smaller blur when the aperture is stopped down. Points are considered acceptably sharp when this blur is below the chosen limit.');

  txt(scene, 'near limit', xD1 + 32, cy + 72, 14, '#444', false, 'start').opacity(0.72);
  txt(scene, 'far limit', xD2 - 36, cy + 72, 14, '#444', false, 'end').opacity(0.72);

  var readout = 'N = f/' + n.toFixed(1) + '   D₁ ≈ ' + lim.near.toFixed(1) + '   U = ' + u.toFixed(1) + '   D₂ ≈ ' + (lim.far > 99 ? '∞' : lim.far.toFixed(1));
  txt(scene, readout, 590, 34, 18, '#333', false, 'middle');

  addTip(scene.rect(170, 180).move(sensorX - 40, 245).fill('#fff').opacity(0.01), 'Sensor plane', 'Sensor plane', 'The red sensor plane is where the camera records the image. If the ray cone has not collapsed to a point here, it records a blur circle.');
  addTip(scene.rect(170, 540).move(xU - 85, 70).fill('#fff').opacity(0.01), 'Object plane at focused distance U', 'Object plane', 'Changing U refocuses the system for a different object distance. The near and far acceptable-focus limits move nonlinearly around it.');
}

function update_apertureFNumber(v) {
  state.apertureFNumber = v;
  render();
}

function update_objectDistanceU(v) {
  state.objectDistanceU = v;
  render();
}

function setControl(id, val) {
  var inp = document.getElementById(id + 'Input');
  var out = document.getElementById(id + 'Val');
  if (inp) inp.value = val;
  if (out) out.value = val;
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(steps.length - 1, i));
  var st = steps[currentStep].state;
  state.apertureFNumber = st.apertureFNumber;
  state.objectDistanceU = st.objectDistanceU;
  setControl('apertureFNumber', state.apertureFNumber);
  setControl('objectDistanceU', state.objectDistanceU);
  document.getElementById('demoNarration').textContent = steps[currentStep].narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + steps.length + ' — ' + steps[currentStep].title;
  render();
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

