  return line(g, x1, y1, x2, y2, black, width == null ? 1.3 : width, opacity == null ? 1 : opacity)
    .attr({ 'stroke-dasharray': '1.5,5' });
}

function textAt(g, s, x, y, size, fill, italic, anchor) {
  var t = g.text(s).font({
    family: 'Georgia, Times New Roman, serif',
    size: size,
    anchor: anchor || 'middle',
    style: italic ? 'italic' : 'normal'
  }).fill(fill || black);
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': Math.max(2, size * 0.11), 'stroke-linejoin': 'round' });
  if (anchor === 'start') t.move(x, y - size * 0.55);
  else if (anchor === 'end') t.move(x - t.length(), y - size * 0.55);
  else t.center(x, y);
  return t;
}

function arrowHead(g, x, y, angle, color, size) {
  var s = size || 13;
  var p1 = [x, y];
  var p2 = [x - s * Math.cos(angle - 0.46), y - s * Math.sin(angle - 0.46)];
  var p3 = [x - s * Math.cos(angle + 0.46), y - s * Math.sin(angle + 0.46)];
  return g.polygon([p1, p2, p3].map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color || black);
}

function arrow(g, x1, y1, x2, y2, color, width, both) {
  var a = Math.atan2(y2 - y1, x2 - x1);
  line(g, x1, y1, x2, y2, color, width || 3);
  arrowHead(g, x2, y2, a, color, 16);
  if (both) arrowHead(g, x1, y1, a + Math.PI, color, 16);
}

function bracket(g, x, y1, y2, label) {
  line(g, x, y1, x, y2, black, 2);
  line(g, x - 11, y1, x + 11, y1, black, 2);
  line(g, x - 11, y2, x + 11, y2, black, 2);
  textAt(g, label, x + 34, (y1 + y2) / 2, 27, black, false, 'middle');
}

function lensShape(g, x, cy, half, apHalf) {
  line(g, x, cy - half - 5, x, cy + half + 5, blue, 2.4);
  var path = 'M ' + (x - 6) + ' ' + (cy - half) +
    ' C ' + (x - 28) + ' ' + (cy - half * 0.55) + ' ' + (x - 28) + ' ' + (cy + half * 0.55) + ' ' + (x - 6) + ' ' + (cy + half) +
    ' M ' + (x + 6) + ' ' + (cy - half) +
    ' C ' + (x + 28) + ' ' + (cy - half * 0.55) + ' ' + (x + 28) + ' ' + (cy + half * 0.55) + ' ' + (x + 6) + ' ' + (cy + half);
  var lens = g.path(path).fill('none').stroke({ color: black, width: 3.2, linecap: 'round' });
  line(g, x - 26, cy - half, x - 26, cy - apHalf, black, 2.3);
  line(g, x - 26, cy + apHalf, x - 26, cy + half, black, 2.3);
  line(g, x + 26, cy - half, x + 26, cy - apHalf, black, 2.3);
  line(g, x + 26, cy + apHalf, x + 26, cy + half, black, 2.3);
  line(g, x - 26, cy - apHalf, x + 26, cy - apHalf, black, 2.3);
  line(g, x - 26, cy + apHalf, x + 26, cy + apHalf, black, 2.3);
  return lens;
}

function dofForN(N, isBottom) {
  var far = 80 + 45 * N;
  var near = 58 + 23 * N;
  if (isBottom) {
    far = 80 + 55 * (4 * N);
    near = 62 + 31 * (4 * N);
  }
  return {
    farLen: Math.min(isBottom ? 520 : 245, far),
    nearLen: Math.min(isBottom ? 330 : 170, near)
  };
}

function drawMeasurementPanel(g, p) {
  var cy = p.cy, objX = p.objX, lensX = p.lensX, farX = p.farX, nearX = p.nearX;
  var yD2 = cy + p.d2y, yD1 = cy + p.d1y, yDof = cy + p.dofy, yU = cy + p.uy;
  dotted(g, farX, cy + 18, farX, yDof + 120, 2.1);
  dotted(g, objX, cy + 16, objX, yU + 12, 1.15);
  dotted(g, nearX, cy + 22, nearX, yDof + 120, 2.1);

  dotted(g, farX, yD2, objX, yD2, 1.25);
  dotted(g, objX, yD1, nearX, yD1, 1.25);
  textAt(g, 'D₂' + p.sup, (farX + objX) / 2, yD2 - 20, 31, black, true);
  textAt(g, 'D₁' + p.sup, (objX + nearX) / 2, yD1 - 20, 31, black, true);

  var center = (farX + nearX) / 2;
  var gap = 105;
  dotted(g, farX, yDof, center - gap, yDof, 1.25);
  dotted(g, center + gap, yDof, nearX, yDof, 1.25);
  line(g, farX, yDof - 16, farX, yDof + 16, black, 1.1).attr({ 'stroke-dasharray': '1.5,5' });
  line(g, nearX, yDof - 16, nearX, yDof + 16, black, 1.1).attr({ 'stroke-dasharray': '1.5,5' });
  textAt(g, 'depth of field', center, yDof + 3, 24, black, false);

  dotted(g, objX, yU, lensX, yU, 1.25);
  textAt(g, 'U', (objX + lensX) / 2, yU - 22, 34, black, true);
}

function drawPanel(g, opts) {
  var cy = opts.cy;
  var lensX = 1040;
  var sensorX = 1260;
  var objX = 560;
  var lensHalf = 142;
  var N = opts.N;
  var apHalf = Math.max(14, Math.min(92, 170 / N));
  var dof = dofForN(state.wideCaseFNumber, opts.bottom);
  var farX = objX - dof.farLen;
  var nearX = objX + dof.nearLen;
  var sup = opts.sup;

  line(g, 35, cy, 1510, cy, '#dddddd', 1.0, 0.45);
  line(g, objX, cy - 230, objX, cy + 245, planeRed, 1.0, 0.9);
  line(g, sensorX, cy - 230, sensorX, cy + 240, planeRed, 1.0, 0.9);
  var lens = lensShape(g, lensX, cy, lensHalf, apHalf);
  addTip(lens, opts.bottom ? 'Narrowed aperture: smaller ray cone' : 'Wide aperture: larger ray cone',
    'Aperture and ray cone',
    opts.bottom ? 'Stopping down the aperture reduces the cone angle. The same defocus therefore cuts a smaller blur at the sensor.' : 'A wide aperture admits steep marginal rays. Defocused points make a larger blur at the sensor, shortening the acceptable-focus range.');

  var apertureLabel = 'A' + sup + ' = f/N' + sup;
  textAt(g, apertureLabel, lensX - 92, cy + 16, 29, black, true);
  bracket(g, lensX - 34, cy - apHalf, cy + apHalf, '');
  textAt(g, 'f', lensX - 28, cy - apHalf - 35, 29, black, true);

  if (!opts.bottom) {
    textAt(g, 'object plane', objX + 15, cy - 178, 24, black, false);
    textAt(g, 'sensor plane', sensorX + 122, cy - 174, 24, black, false);
  }

  var yTop = cy - apHalf;
  var yBot = cy + apHalf;

  line(g, objX, cy, lensX, yTop, blue, 2.4, 0.98);
  line(g, objX, cy, lensX, yBot, blue, 2.4, 0.98);
  line(g, lensX, yTop, sensorX, cy, blue, 2.4, 0.98);
  line(g, lensX, yBot, sensorX, cy, blue, 2.4, 0.98);

  var defocusX = farX;
  var convX = sensorX + 64;
  line(g, defocusX, cy, lensX, yTop, lightBlue, 1.05, 0.93);
  line(g, defocusX, cy, lensX, yBot, lightBlue, 1.05, 0.93);
  line(g, lensX, yTop, convX, cy, lightBlue, 1.05, 0.93);
  line(g, lensX, yBot, convX, cy, lightBlue, 1.05, 0.93);

  var blur = apHalf * (sensorX - lensX) / (convX - lensX);
  var bTop = cy - blur, bBot = cy + blur;
  line(g, sensorX, bTop, sensorX, bBot, black, 2.0);
  line(g, sensorX - 12, bTop, sensorX + 12, bTop, black, 1.8);
  line(g, sensorX - 12, bBot, sensorX + 12, bBot, black, 1.8);
  textAt(g, 'C', sensorX + 38, cy, 26, black, false);
  if (!opts.bottom) {
    textAt(g, 'circle of', sensorX + 115, cy - 18, 23, black, false, 'start');
    textAt(g, 'confusion', sensorX + 115, cy + 20, 23, black, false, 'start');
