  var nearConvX = sensorX - 48;
  line(g, nearX, cy, lensX, yTop, blue, 2.0, 0.95);
  line(g, nearX, cy, lensX, yBot, blue, 2.0, 0.95);
  line(g, lensX, yTop, sensorX + 28, cy + apHalf * 0.48, blue, 2.0, 0.95);
  line(g, lensX, yBot, sensorX + 28, cy - apHalf * 0.48, blue, 2.0, 0.95);
  line(g, lensX, yTop, nearConvX, cy, lightBlue, 1.0, 0.65);
  line(g, lensX, yBot, nearConvX, cy, lightBlue, 1.0, 0.65);

  drawMeasurementPanel(g, {
    cy: cy,
    lensX: lensX,
    objX: objX,
    farX: farX,
    nearX: nearX,
    sup: sup,
    d2y: opts.bottom ? 182 : 150,
    d1y: opts.bottom ? 196 : 164,
    dofy: opts.bottom ? 252 : 226,
    uy: opts.bottom ? 330 : 326
  });

  var objHit = g.circle(11).center(objX, cy).fill('#fff').opacity(0.001);
  addTip(objHit, 'Focused object plane at distance U', 'Focused object distance',
    'Both panels use the same focused object distance U. The comparison isolates the effect of aperture size.');
  var sensHit = g.rect(58, 260).move(sensorX - 29, cy - 130).fill('#fff').opacity(0.001);
  addTip(sensHit, 'Image/sensor plane where blur C is measured', 'Circle of confusion',
    'A defocused ray cone is sliced by the sensor plane. A narrower aperture makes this slice smaller.');
  var dofHit = g.rect(Math.max(20, nearX - farX), 44).move(farX, cy + opts.dofy - 22).fill('#fff').opacity(0.001);
  addTip(dofHit, opts.bottom ? 'Larger depth of field for the stopped-down case' : 'Shorter depth of field for the wide-aperture case',
    'Depth of field',
    opts.bottom ? 'Case b accepts a wider range of object distances because its blur circles stay small over a longer interval.' : 'Case a has a wide aperture, so the acceptable near and far limits are closer together.');
}

function drawRedAnnotations(g) {
