  arrow(g, lensX + 58, cy + 168, lensX + 58, cy + opening + 14, red, 4, false);
  textAt(g, 'narrowed', lensX + 96, cy + 92, 24, red, false, 'start');
  textAt(g, 'aperture', lensX + 96, cy + 130, 24, red, false, 'start');
