  dotted(g, sensorX, bTop, bx, bTop, 2.0);
  dotted(g, sensorX, bBot, bx, bBot, 2.0);
  bracket(g, bx, bTop, bBot, 'C', 42, 49);

  if (!bottom) {
    textAt(g, 'circle of', bx + 135, cy - 26, 41, black, false, 'start');
    textAt(g, 'confusion', bx + 135, cy + 35, 41, black, false, 'start');
  }

  var sensHit = g.rect(116, 126).move(sensorX - 18, cy - 63).fill('#fff').opacity(0.001);
  addTip(sensHit, 'Circle of confusion C: the blur diameter made where the sensor cuts a defocused cone.',
    'Circle of confusion',
    'The acceptable blur diameter is marked by the C bracket. For a narrower aperture the same focus error produces a smaller slice of the cone at the image plane.');
}

function drawRayBundles(g, cy, farX, nearX, apHalf, bottom) {
  var objX = geom.objX, lensX = geom.lensX, sensorX = geom.sensorX;

  line(g, objX, cy, lensX, cy - apHalf, blue, 4.1, 1);
  line(g, objX, cy, lensX, cy + apHalf, blue, 4.1, 1);
  line(g, lensX, cy - apHalf, sensorX, cy, blue, 4.1, 1);
  line(g, lensX, cy + apHalf, sensorX, cy, blue, 4.1, 1);

  var cBlur = bottom ? 28 : 29;
  line(g, farX, cy, lensX, cy - apHalf, lightBlue, 2.0, 0.95);
  line(g, farX, cy, lensX, cy + apHalf, lightBlue, 2.0, 0.95);
  line(g, lensX, cy - apHalf, sensorX, cy - cBlur, lightBlue, 2.0, 0.95);
  line(g, lensX, cy + apHalf, sensorX, cy + cBlur, lightBlue, 2.0, 0.95);
  line(g, sensorX, cy - cBlur, sensorX + 82, cy - cBlur - 78, lightBlue, 2.0, 0.85);
  line(g, sensorX, cy + cBlur, sensorX + 82, cy + cBlur + 78, lightBlue, 2.0, 0.85);

  line(g, nearX, cy, lensX, cy - apHalf, blue, 3.6, 0.98);
  line(g, nearX, cy, lensX, cy + apHalf, blue, 3.6, 0.98);
  line(g, lensX, cy - apHalf, sensorX + 52, cy + (bottom ? 52 : 65), blue, 3.6, 0.98);
  line(g, lensX, cy + apHalf, sensorX + 52, cy - (bottom ? 52 : 65), blue, 3.6, 0.98);

  line(g, lensX, cy - apHalf, sensorX - 116, cy, lightBlue, 1.7, 0.73);
  line(g, lensX, cy + apHalf, sensorX - 116, cy, lightBlue, 1.7, 0.73);

  var objHit = g.circle(22).center(objX, cy).fill('#fff').opacity(0.001);
  addTip(objHit, 'Same focused object distance U in both panels.',
    'Focused object distance',
    'The two cases keep the focused object distance fixed. The change in depth of field comes from the aperture, not from moving the focused plane.');
}

function drawTopApproxAnnotation(g, cy, farX) {
  line(g, farX, cy - 8, geom.objX, cy - 78, lightBlue, 1.9, 0.95);
  line(g, farX, cy + 8, geom.objX, cy + 78, lightBlue, 1.9, 0.95);
  dottedBracket(g, farX, cy - 45, cy + 45);
  drawApproxCUOverF(g, 928, cy + 12);
}

function drawPanel(g, opts) {
  var cy = opts.cy;
  var bottom = opts.bottom;
  var sup = opts.sup;
  var N = opts.N;
  var fullHalf = geom.lensHalf;
  var apHalf = bottom ? apertureHalfForBottom(state.wideCaseFNumber) : apertureHalfForTop(state.wideCaseFNumber);
  var dof = dofForN(state.wideCaseFNumber, bottom);
  var farX = geom.objX - dof.d2;
  var nearX = geom.objX + dof.d1;

  line(g, 40, cy, 2460, cy, '#d9d9d9', 1.2, 0.35);

  var lens = lensShape(g, geom.lensX, cy, fullHalf, apHalf, bottom);
  addTip(lens,
    bottom ? 'Narrowed aperture: the ray cone is slimmer.' : 'Wide aperture: the marginal rays make a steep cone.',
    'Aperture and ray cone',
    bottom ? 'Stopping down reduces the cone angle. A defocused object must move farther before its blur reaches the same acceptable circle C.' : 'A wide opening creates steep marginal rays, so a small defocus makes a relatively large blur at the sensor.');

  drawRayBundles(g, cy, farX, nearX, apHalf, bottom);
  drawCircleOfConfusion(g, cy, apHalf, bottom);

  var bx = geom.lensX - 56;
  bracket(g, bx, cy - apHalf, cy + apHalf, '', 34, 32);
  textAt(g, 'f', bx + 14, cy - apHalf - 58, 50, black, true, 'middle');

  if (bottom) {
    drawFormula(g, geom.lensX - 198, cy - 2, sup, 48);
  } else {
    drawFormula(g, geom.lensX - 205, cy - 10, sup, 48);
  }

  if (!bottom) drawTopApproxAnnotation(g, cy, farX);

  drawMeasurementPanel(g, {
    cy: cy,
    farX: farX,
    nearX: nearX,
    sup: sup,
    bottom: bottom,
    yD2: bottom ? 1718 : 684,
    yD1: bottom ? 1746 : 712,
    yDof: bottom ? 1855 : 822,
    yU: bottom ? 1952 : 1004,
    vBottom: bottom ? 1918 : 1236
  });
}

function drawRedAnnotations(g) {
  arrow(g, 760, 1276, 86, 1276, red, 6, false);
  textAt(g, 'larger depth of field', 420, 1238, 41, red, false);
  arrow(g, 1265, 1278, 1360, 1278, red, 6, false);

  var lensX = geom.lensX, cy = geom.botCy, opening = apertureHalfForBottom(state.wideCaseFNumber);
  arrow(g, lensX + 33, cy - 300, lensX + 33, cy - opening - 10, red, 6, false);
  arrow(g, lensX + 33, cy + 300, lensX + 33, cy + opening + 10, red, 6, false);
  textAt(g, 'narrowed', lensX + 78, cy + 172, 41, red, false, 'start');
  textAt(g, 'aperture', lensX + 78, cy + 232, 41, red, false, 'start');

  var hit = g.rect(440, 110).move(92, 1192).fill('#fff').opacity(0.001);
  addTip(hit, 'The lower case is annotated as having the larger depth of field.',
    'Larger depth of field',
    'Because the lower aperture is narrower, the far and near acceptable-focus limits are spread farther apart than in the upper case.');
}

function render() {
  scene.clear();
  scene.rect(W, H).fill('#ffffff');

  drawGlobalReferencePlanes(scene);
  drawPlaneLabels(scene);

  var Na = state.wideCaseFNumber;
  var Nb = 4 * Na;

  drawPanel(scene, { cy: geom.topCy, N: Na, sup: 'ᵃ', bottom: false });
  drawPanel(scene, { cy: geom.botCy, N: Nb, sup: 'ᵇ', bottom: true });
  drawRedAnnotations(scene);
}

function update_wideCaseFNumber(v) {
  state.wideCaseFNumber = v;
  render();
}

function setControl(id, val) {
  var inp = document.getElementById(id + 'Input');
  var out = document.getElementById(id + 'Val');
  if (inp) inp.value = val;
  if (out) out.value = val;
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(steps.length - 1, i));
  state.wideCaseFNumber = steps[currentStep].state.wideCaseFNumber;
  setControl('wideCaseFNumber', state.wideCaseFNumber);
  var narr = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (narr) narr.textContent = steps[currentStep].narration;
  if (lab) lab.textContent = (currentStep + 1) + '/' + steps.length + ' — ' + steps[currentStep].title;
  render();
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

applyStep(0);
window.__markRendered();
